  source: '剑桥雅思6',
  sentence: 'As researchers on aging noted recently, no treatment on the market today has been proved to slow human aging—the build-up of molecular and cellular damage that increase vulnerability to infirmity as we grow older.',
  translation: '就像老龄化研究者最近所指出的那样，目前市面上没有一种疗法被证实可以减缓人体衰老——随着我们慢慢变老，分子与细胞损坏也逐渐增加，这就增加了我们体弱多病的几率。',
  grammarNote: '本句主干是no treatment has been proved to slow human aging。句首 as引导定语从句，修饰后面整个主句。破折号后面the build-up ... grow older是human aging的同位语，进一步解释human aging。that引导定语从句that increase ... grow older修饰the build-up of molecular and cellular damage；句末的as引导时间状语从句，表示“当…时候，随着”。',
