  source: '剑桥雅思8',
  sentence: 'We tend to think of climate—as opposed to weather—as something unchanging, yet humanity has been at the mercy of climate change for its entire existence, with at least eight glacial episodes in the past 730,000 years.',
  translation: '我们往往认为气候相对于天气而言是不变的，然而，人类的存在却一直受制于气候的变化，在过去的73万年里至少经历了8 个冰河时期。',
  grammarNote: '本句是一个yet连接的并列句，yet在此处作并列连词，表示“然而”， 前一分句的主干是We tend to think of climate as something unchanging， 后一分句的主干是humanity has been at the mercy of climate change。破折号之间as opposed to weather作插入语，解释说明climate。as opposed to sth.是一个固定搭配，意为“与某事物相反”。句末的with... in the past 730,000 years作伴随状语。',
