  source: '剑桥雅思9',
  sentence: 'On the negative side, this type of organisation doesn\'t always act effectively, because it depends too much on one or two people at the top, and when these people make poor decisions there\'s no-one else who can influence them.',
  translation: '不利的一面是，这种类型的组织方式并不总是有效的，因为它主要依靠一两个高层领导人物，当这些人做了糟糕的决策时， 没有人能够影响得了他们。',
  grammarNote: '本句的主干是this type of organisation doesn\'t always act effectively。 在这句话中，because引导原因状语从句because it ... influence them，在这个原因状语从句中when引导时间状语从句，who引导定语从句修饰no- one else。',
