  source: '剑桥雅思12',
  sentence: 'Many CEOs combine two opposing characteristics: confidence —that is, the belief that they\'re capable of great achievements— with a high level of anxiety, a fear of missing targets, whether set by themselves or by the directors of the company.',
  translation: '许多CEO都有两种相反的特征：自信——即相信自己有能力取得巨大成就——高度的焦虑，害怕自己或公司董事设定的目标落空。',
  grammarNote: '本句的主干是Many CEOs combine two opposing characteristics。冒号后的内容是对前面two opposing characteristics的具体阐述，that is, the belief that they\'re capable of great achievements对confidence起到解释说明的作用；a fear of missing targets作插入语，解释a high level of anxiety； whether引导让步状语从句，whether后省略了they are。',
