  grammarNote: '本句的主干是A radical solution is the professional board。which在此处引导非限制性定语从句，修饰先行词solution；定语从句whose businesses are extensive and complex修饰large companies；第二个whose 引导的非限制性定语从句，进一步对the professional board进行说明，过去分词短语supported by their own dedicated staff and advisers表被动，作伴随状语。',
