  source: '剑桥雅思10',
  sentence: 'The antiseptic properties of tannin, the active ingredient in tea, and of hops in beer—plus the fact that both are made with boiled water—allowed urban communities to flourish at close quarters without succumbing to water-borne diseases such as dysentery.',
  translation: '茶中的活性成分单宁和啤酒中的啤酒花这两种物质的抗菌性能，加上它们都是用开水制作加工的事实，使城市社群在拥挤的区域得以繁荣，免遭诸如痢疾之类的水传播疾病。',
