  source: '剑桥雅思9',
  sentence: 'As recently as 1993, engineers made a major breakthrough by discovering so-called turbo codes—which come very close to Shannon\'s ultimate limit for the maximum rate that data can be transmitted reliably, and now play a key role in the mobile videophone revolution.',
